// The Mac's own general pasteboard, for the shared clipboard
// (internal/clipshare/hostpb.go). This is the opposite of -pasteboard, which
// reaches a simulator's pasteboard through a private, uniquely named one and
// never touches the Mac's.
//
// NSPasteboard posts no notification on change, so changeCount is polled
// every 250ms. Out, one line per change: `text <base64 of UTF-8>`, or
// `confidential` for an item a password manager marked as concealed,
// transient or auto-generated (nspasteboard.org). In: `set <base64>` sets the
// pasteboard, and the changeCount that produces is not reported back.
// It exits when stdin closes.

import AppKit
import Foundation

// The nspasteboard.org markers. An item carrying any of them stays on this Mac.
private let concealedTypes: Set<NSPasteboard.PasteboardType> = [
    NSPasteboard.PasteboardType("org.nspasteboard.ConcealedType"),
    NSPasteboard.PasteboardType("org.nspasteboard.TransientType"),
    NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType"),
]

func runHostPasteboard() -> Never {
    let pb = NSPasteboard.general
    // Read and written on the main queue only.
    var lastCount = pb.changeCount
    var lastSetCount = -1

    Thread.detachNewThread {
        while let line = readLine() {
            guard line.hasPrefix("set "), let data = Data(base64Encoded: String(line.dropFirst(4))),
                  let text = String(data: data, encoding: .utf8) else { continue }
            DispatchQueue.main.async {
                pb.clearContents()
                pb.setString(text, forType: .string)
                lastSetCount = pb.changeCount
                lastCount = lastSetCount
            }
        }
        exit(0)
    }

    let timer = DispatchSource.makeTimerSource(queue: .main)
    timer.schedule(deadline: .now() + .milliseconds(250), repeating: .milliseconds(250))
    timer.setEventHandler {
        let count = pb.changeCount
        guard count != lastCount else { return }
        lastCount = count
        if count == lastSetCount { return }
        if let types = pb.types, !concealedTypes.isDisjoint(with: types) {
            print("confidential")
        } else if let text = pb.string(forType: .string), !text.isEmpty {
            print("text \(Data(text.utf8).base64EncodedString())")
        } else {
            return
        }
        fflush(stdout)
    }
    timer.resume()
    dispatchMain()
}
